from pathlib import Path
import json
B=Path(__file__).resolve().parent.parent;L=B/'reports/latex/tables';L.mkdir(exist_ok=True);src=json.load(open(B/'results/data/source_tables.json'));out=[]
def esc(x):return str(x).replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
def table(idx,cap,headers,rows,spec=None,note=''):
 spec=spec or ('@{}'+'X'*len(headers)+'@{}');s='\\begin{table}[htbp]\n\\caption{'+cap+'}\n\\label{tab:src'+str(idx)+'}\n\\small\n\\setlength{\\tabcolsep}{3.5pt}\n\\begin{tabularx}{\\linewidth}{'+spec+'}\n\\toprule\n'+' & '.join(headers)+r' \\'+'\n\\midrule\n'+'\n'.join(' & '.join(map(str,r))+r' \\' for r in rows)+'\n\\bottomrule\n\\end{tabularx}\n'+(('\\par\\smallskip{\\footnotesize '+note+'}\n') if note else'')+'\\end{table}\n';(L/f'source{idx:02d}.tex').write_text(s);out.append(dict(source_table_index=idx,label='tab:src'+str(idx),caption=cap,source_rows=len(src[idx])-1,typeset_rows=len(rows)))
# Source index follows the actual zero-based Word table order, never other simulation records.
table(4,'Parameters of the supplied simulation study.',['Parameter','Value','Basis / status'],[
['Dry mass; dimensions','130 t; 65 m; 7.0 m','Problem data (G)'],['Separation altitude; speed','70 km; 1666.667 m/s','Problem data (G)'],['Initial flight-path angle',r'$45^\circ$','Scenario (H)'],['Engine system',r'$7\times1$ MN; $I_{sp}=330$ s','Virtual reference (H)'],['Oxygen/methane ratio','3.4','Scenario (H)'],['Reference area',r'38.4845 m$^2$','Derived from diameter (D)'],['Mach-dependent drag',r'12 anchors; maximum $C_D=1.50$','Source drag model (H)'],['Atmosphere',r'USSA 1976 layers; exponential above 86 km','Reference plus extension'],['Earth',r'$R_E=6371$ km; $\mu=3.986\times10^{14}$ m$^3$/s$^2$','Reference constants'],['Wind profile','Height-dependent; see Table~\\ref{tab:src3}','Scenario (H)'],['Pressure limit','50 kPa','Screening target (H)'],['Target touchdown speed','1.5 m/s; baseline test below 3 m/s','Guidance and acceptance choices (H)']],spec=r'@{}p{.26\linewidth}p{.36\linewidth}X@{}')
table(3,'Along-track wind anchors retained from the source.',['Altitude','Wind (m/s)','Interpretation'],[['0--100 m','8','Sea wind'],['2 km','15','Boundary layer'],['11 km','35','Jet-level anchor'],['20 km','20','Lower stratosphere'],['Above 20 km',r'$20e^{-(h_{\rm km}-20)/15}$','Exponential decay']],spec='@{}lXX@{}')
rows=[]
for row in src[2][1:]:rows.append([row[0],'Exhausted' if '失败' in row[1] else 'Pass']+row[2:])
table(2,'Reported baseline load scan; fuel entries include both oxygen and methane.',['Load (t)','Outcome',r'$V_{td}$ (m/s)','Entry (t)','Landing (t)',r'$q_{\max}$ (kPa)',r'$n_{\max}$','Time (s)'],rows,spec='@{}rlrrrrrr@{}')
table(6,'Source stage history for the 150 t baseline case.',['Phase','Time (s)','Altitude (km)','Speed (m/s)',r'$\gamma$ (deg)','Description'],[
['Ascent','0--127','70--143','1667--1165','45--0','Unpowered arc'],['Descent','127--245','143--75','1165--1632','0 to -44','Gravity accelerates'],['Entry burn','245--265','75--55','1632--1300','-44 to -50','7 MN; 41.2 t'],['Transition','265--272','55--47','1300--1289','-50 to -51','Unpowered, 7 s'],['Terminal burn','272--365','47--0','1289--2.5','-51 to -90','Throttle control; 90.1 t'],['Touchdown','365','0','2.5','-90','Reported cutoff event']],spec=r'@{}p{.16\linewidth}rrrrX@{}')
table(7,'Reported entry-burn characteristics.',['Quantity','Source value'],[['Thrust','7 engines at 1 MN: 7 MN combined'],['Direction',r'Opposite air-relative velocity; reported vertical-reference deflection $-45.9^\circ$ at $\gamma=-44^\circ$'],['Duration','About 20 s'],['Propellant','40--44 t across the baseline load scan'],['Velocity reduction','Approximately 300--350 m/s']],spec=r'@{}p{.22\linewidth}X@{}')
table(8,'Reported terminal-burn characteristics of the baseline.',['Quantity','Source value'],[['Thrust','5.9 MN at ignition; 7 MN peak; 2.1 MN near touchdown'],['Direction',r'Opposite ground velocity; reported vertical-reference deflection changes from $-38.7^\circ$ to $-0.3^\circ$'],['Duration','About 90 s for the 150 t baseline case'],['Propellant','51--121 t across the baseline load scan'],['Effect','About 1289 m/s to 2.5 m/s; peak pressure about 47.6 kPa']],spec=r'@{}p{.22\linewidth}X@{}')
def outcome(s,typ):
 if s=='✓':return 'Pass'
 if s.startswith('✓'):return 'Pass: '+s.replace('✓','').replace('（','(').replace('）',')').strip()
 return 'Fail: '+s.replace('✗','').strip() if s!='✗' else'Fail'
table(5,'Source baseline perturbation tests. Failed numerical entries are terminal speeds in m/s; parenthesized successful entries are remaining propellant in tonnes.',['Load (t)','Nominal',r'$C_D-15\%$',r'$C_D-20\%$',r'$I_{sp}-2\%$',r'Wind $\times3$','Combined'],[[r[0]]+[outcome(c,'') for c in r[1:]] for r in src[5][1:]],spec='@{}rXXXXXX@{}')
